package dev.gbppimentel.zzz;
public final class AuthRecoveryTest{public static void main(String[] args){String c=AuthRecovery.freshBadgeCookies("e_nap_token=old; e_lrsag=risk; SERVERID=old-route; SERVERCORSID=affinity; ltoken_v2=keep; cookie_token_v2=keep-too; ltuid_v2=123;");if(c.contains("old")||c.contains("risk")||c.contains("affinity"))throw new AssertionError("Stale badge pair and route cookies must be dropped together");if(!c.contains("ltoken_v2=keep")||!c.contains("cookie_token_v2=keep-too")||!c.contains("ltuid_v2=123"))throw new AssertionError("Core account cookies must survive scoped recovery");if(!AuthRecovery.expired(-100)||AuthRecovery.verification(-100)||!AuthRecovery.verification(1034)||AuthRecovery.expired(429))throw new AssertionError("Scoped expiry, verification and rate limits must differ");System.out.println("3 scoped-auth recovery checks passed");}}
